function resourcePdfFor(id) {
    return (typeof RESOURCE_PDF_MAP !== 'undefined' && RESOURCE_PDF_MAP[id]) ? RESOURCE_PDF_MAP[id] : null;
}

function buildResourceCard(item, cat) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'resource-card-tile';
    card.setAttribute('aria-haspopup', 'dialog');
    const pdf = resourcePdfFor(item.id);
    const ctaLabel = item.type === 'links' ? 'VIEW GUIDES' : 'READ GUIDE';
    card.innerHTML = `
        <span class="resource-card-badge">${cat.num} &middot; ${cat.label}</span>
        <h3>${item.title}</h3>
        <p>${item.description}</p>
        <span class="resource-card-foot"><span class="resource-card-cta">${ctaLabel} &rarr;</span>${pdf ? '<span class="resource-pdf-flag">PDF</span>' : ''}</span>
    `;
    card.addEventListener('click', () => openResourceModal(item, cat));
    return card;
}

function openResourceModal(item, cat) {
    const overlay = document.getElementById('resource-modal-overlay');
    const panel = document.getElementById('resource-modal-panel');
    if (!overlay || !panel) return;
    const pdf = resourcePdfFor(item.id);

    let bodyHtml;
    let footerHtml = '';
    if (item.type === 'links') {
        bodyHtml = `<div class="resource-modal-links">${item.content}</div>`;
    } else {
        bodyHtml = item.content;
        footerHtml = pdf
            ? `<a class="btn-primary resource-download-btn" href="${pdf}" target="_blank" rel="noopener">DOWNLOAD PDF &darr;</a>`
            : `<span class="resource-download-pending">Downloadable PDF coming soon</span>`;
    }

    panel.innerHTML = `
        <button type="button" class="resource-modal-close" aria-label="Close">&times;</button>
        <span class="resource-card-badge">${cat.num} &middot; ${cat.label}</span>
        <h2>${item.title}</h2>
        <div class="resource-modal-body">${bodyHtml}</div>
        ${footerHtml ? `<div class="resource-modal-footer">${footerHtml}</div>` : ''}
    `;
    panel.querySelector('.resource-modal-close').addEventListener('click', closeResourceModal);
    overlay.classList.add('active');
    overlay.setAttribute('aria-hidden', 'false');
    document.body.classList.add('resource-modal-open');
    panel.scrollTop = 0;
    panel.querySelector('.resource-modal-close').focus();
}

function closeResourceModal() {
    const overlay = document.getElementById('resource-modal-overlay');
    if (!overlay) return;
    overlay.classList.remove('active');
    overlay.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('resource-modal-open');
}

function setActiveResourceCategory(catId, scrollIntoView) {
    document.querySelectorAll('.resource-library-nav button').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.cat === catId);
    });
    document.querySelectorAll('.resource-category-block').forEach(block => {
        block.hidden = block.dataset.cat !== catId;
    });
    if (scrollIntoView) {
        const root = document.getElementById('resource-grid-root');
        if (root) root.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

function initResourceHub() {
    const gridRoot = document.getElementById('resource-grid-root');
    const navRoot = document.getElementById('resource-hub-nav');
    if (!gridRoot || !navRoot) return;

    if (!document.getElementById('resource-modal-overlay')) {
        const overlay = document.createElement('div');
        overlay.id = 'resource-modal-overlay';
        overlay.className = 'resource-modal-overlay';
        overlay.setAttribute('aria-hidden', 'true');
        overlay.innerHTML = '<div class="resource-modal-panel" id="resource-modal-panel" role="dialog" aria-modal="true"></div>';
        document.body.appendChild(overlay);
        overlay.addEventListener('click', event => { if (event.target === overlay) closeResourceModal(); });
        document.addEventListener('keydown', event => { if (event.key === 'Escape') closeResourceModal(); });
    }

    let firstCatId = null;

    RESOURCE_CATEGORY_GROUPS.forEach(group => {
        group.cats.forEach(cat => {
            const items = RESOURCE_ITEMS.filter(entry => entry.category === cat.id);
            if (!items.length) return;
            if (!firstCatId) firstCatId = cat.id;

            const navBtn = document.createElement('button');
            navBtn.type = 'button';
            navBtn.dataset.cat = cat.id;
            navBtn.innerHTML = `${cat.num} &middot; ${cat.label}`;
            navBtn.addEventListener('click', () => setActiveResourceCategory(cat.id, true));
            navRoot.appendChild(navBtn);

            const section = document.createElement('div');
            section.className = 'resource-category-block';
            section.dataset.cat = cat.id;
            section.hidden = true;
            const heading = document.createElement('div');
            heading.className = 'resource-category-heading';
            heading.innerHTML = `<span>${cat.num} &middot; ${cat.label}</span>`;
            section.appendChild(heading);

            const grid = document.createElement('div');
            grid.className = 'resource-card-grid';
            items.forEach(item => grid.appendChild(buildResourceCard(item, cat)));
            section.appendChild(grid);

            gridRoot.appendChild(section);
        });
    });

    if (firstCatId) setActiveResourceCategory(firstCatId, false);
}

document.addEventListener('DOMContentLoaded', initResourceHub);
